1	// Package ir implements IR generation from optimized AST
2	package ir
3	
4	import (
5		"fmt"
6	
7		"github.com/user/freelang-evolving-compiler/internal/ast"
8	)
9	
10	// Generator converts AST to intermediate representation
11	type Generator struct {
12		tempCount  int
13		labelCount int
14		currentFn  *Function
15		program    *Program
16	}
17	
18	// NewGenerator creates a new IR generator
19	func NewGenerator() *Generator {
20		return &Generator{
21			tempCount:  0,
22			labelCount: 0,
23			program: &Program{
24				Functions: []Function{},
25				Main:      []Instruction{},
26			},
27		}
28	}
29	
30	// Generate converts an AST to an IR program
31	func (g *Generator) Generate(root *ast.Node) (*Program, error) {
32		if root == nil {
33			return g.program, nil
34		}
35	
36		// Process program statements
37		if root.Kind == ast.NodeProgram {
38			for _, child := range root.Children {
39				if child.Kind == ast.NodeFnDecl {
40					if err := g.genFnDecl(child); err != nil {
41						return nil, err
42					}
43				} else {
44					if err := g.genStmt(child); err != nil {
45						return nil, err
46					}
47				}
48			}
49		} else {
50			if err := g.genStmt(root); err != nil {
51				return nil, err
52			}
53		}
54	
55		return g.program, nil
56	}
57	
58	// genFnDecl generates IR for a function declaration
59	func (g *Generator) genFnDecl(node *ast.Node) error {
60		if len(node.Children) < 2 {
61			return fmt.Errorf("function declaration must have name and body")
62		}
63	
64		fnName := node.Children[0].Value
65		body := node.Children[len(node.Children)-1]
66	
67		fn := Function{
68			Name:   fnName,
69			Params: []string{},
70			Body:   []Instruction{},
71		}
72	
73		// Extract parameter names if they exist
74		if len(node.Children) > 2 {
75			for i := 1; i < len(node.Children)-1; i++ {
76				if node.Children[i].Kind == ast.NodeIdent {
77					fn.Params = append(fn.Params, node.Children[i].Value)
78				}
79			}
80		}
81	
82		// Save current function and switch context
83		prevFn := g.currentFn
84		g.currentFn = &fn
85	
86		// Generate OpEnter
87		g.emit(Instruction{Op: OpEnter, Fn: fnName})
88	
89		// Generate body
90		if body.Kind == ast.NodeBlockStmt {
91			for _, stmt := range body.Children {
92				if err := g.genStmt(stmt); err != nil {
93					return err
94				}
95			}
96		} else {
97			if err := g.genStmt(body); err != nil {
98				return err
99			}
100		}
101	
102		// Generate OpLeave if not already there
103		g.emit(Instruction{Op: OpLeave, Fn: fnName})
104	
105		// Add function to program
106		g.program.Functions = append(g.program.Functions, fn)
107		g.currentFn = prevFn
108	
109		return nil
110	}
111	
112	// genStmt generates IR for a statement
113	func (g *Generator) genStmt(node *ast.Node) error {
114		if node == nil {
115			return nil
116		}
117	
118		switch node.Kind {
119		case ast.NodeLetDecl:
120			return g.genLetDecl(node)
121		case ast.NodeIfStmt:
122			return g.genIfStmt(node)
123		case ast.NodeForStmt:
124			return g.genForStmt(node)
125		case ast.NodeReturn:
126			return g.genReturn(node)
127		case ast.NodeBlockStmt:
128			for _, child := range node.Children {
129				if err := g.genStmt(child); err != nil {
130					return err
131				}
132			}
133			return nil
134		default:
135			// Expression statement
136			_, err := g.genExpr(node)
137			return err
138		}
139	}
140	
141	// genLetDecl generates IR for a let declaration
142	func (g *Generator) genLetDecl(node *ast.Node) error {
143		if len(node.Children) < 2 {
144			return fmt.Errorf("let declaration must have name and value")
145		}
146	
147		varName := node.Children[0].Value
148		valueExpr := node.Children[1]
149	
150		// Generate code for the expression
151		operand, err := g.genExpr(valueExpr)
152		if err != nil {
153			return err
154		}
155	
156		// Copy result to variable
157		g.emit(Instruction{
158			Op:   OpCopy,
159			Dest: Operand{Name: varName},
160			Src1: operand,
161		})
162	
163		return nil
164	}
165	
166	// genIfStmt generates IR for an if statement
167	func (g *Generator) genIfStmt(node *ast.Node) error {
168		if len(node.Children) < 2 {
169			return fmt.Errorf("if statement must have condition and body")
170		}
171	
172		condExpr := node.Children[0]
173		bodyStmt := node.Children[1]
174	
175		// Generate condition
176		condOp, err := g.genExpr(condExpr)
177		if err != nil {
178			return err
179		}
180	
181		// Create end label
182		endLabel := g.newLabel("end")
183	
184		// Jump if false
185		g.emit(Instruction{
186			Op:    OpJumpIfFalse,
187			Src1:  condOp,
188			Label: endLabel,
189		})
190	
191		// Generate body
192		if err := g.genStmt(bodyStmt); err != nil {
193			return err
194		}
195	
196		// Emit end label
197		g.emit(Instruction{
198			Op:    OpLabel,
199			Label: endLabel,
200		})
201	
202		return nil
203	}
204	
205	// genForStmt generates IR for a for statement
206	func (g *Generator) genForStmt(node *ast.Node) error {
207		if len(node.Children) < 3 {
208			return fmt.Errorf("for statement must have iterator, range, and body")
209		}
210	
211		iterName := node.Children[0].Value
212		rangeExpr := node.Children[1]
213		bodyStmt := node.Children[2]
214	
215		// Extract range start and end
216		if rangeExpr.Kind != ast.NodeBinaryExpr || rangeExpr.Value != ".." {
217			return fmt.Errorf("for loop requires range expression (..)")
218		}
219	
220		if len(rangeExpr.Children) < 2 {
221			return fmt.Errorf("range expression requires start and end")
222		}
223	
224		startOp, err := g.genExpr(rangeExpr.Children[0])
225		if err != nil {
226			return err
227		}
228	
229		endOp, err := g.genExpr(rangeExpr.Children[1])
230		if err != nil {
231			return err
232		}
233	
234		// Initialize iterator
235		g.emit(Instruction{
236			Op:   OpCopy,
237			Dest: Operand{Name: iterName},
238			Src1: startOp,
239		})
240	
241		// Create loop and end labels
242		loopLabel := g.newLabel("loop")
243		endLabel := g.newLabel("end")
244	
245		// Emit loop label
246		g.emit(Instruction{
247			Op:    OpLabel,
248			Label: loopLabel,
249		})
250	
251		// Check condition: iterator < end
252		cmpTemp := g.newTemp()
253		g.emit(Instruction{
254			Op:   OpLt,
255			Dest: cmpTemp,
256			Src1: Operand{Name: iterName},
257			Src2: endOp,
258		})
259	
260		// Jump if false (exit loop)
261		g.emit(Instruction{
262			Op:    OpJumpIfFalse,
263			Src1:  cmpTemp,
264			Label: endLabel,
265		})
266	
267		// Generate body
268		if err := g.genStmt(bodyStmt); err != nil {
269			return err
270		}
271	
272		// Increment iterator
273		incrTemp := g.newTemp()
274		g.emit(Instruction{
275			Op:   OpAdd,
276			Dest: incrTemp,
277			Src1: Operand{Name: iterName},
278			Src2: Operand{IsImm: true, ImmVal: 1},
279		})
280		g.emit(Instruction{
281			Op:   OpCopy,
282			Dest: Operand{Name: iterName},
283			Src1: incrTemp,
284		})
285	
286		// Jump back to loop
287		g.emit(Instruction{
288			Op:    OpJump,
289			Label: loopLabel,
290		})
291	
292		// Emit end label
293		g.emit(Instruction{
294			Op:    OpLabel,
295			Label: endLabel,
296		})
297	
298		return nil
299	}
300	
301	// genReturn generates IR for a return statement
302	func (g *Generator) genReturn(node *ast.Node) error {
303		if len(node.Children) == 0 {
304			g.emit(Instruction{Op: OpReturn})
305			return nil
306		}
307	
308		returnOp, err := g.genExpr(node.Children[0])
309		if err != nil {
310			return err
311		}
312	
313		g.emit(Instruction{
314			Op:   OpReturn,
315			Src1: returnOp,
316		})
317	
318		return nil
319	}
320	
321	// genExpr generates IR for an expression and returns the operand
322	func (g *Generator) genExpr(node *ast.Node) (Operand, error) {
323		if node == nil {
324			return Operand{}, fmt.Errorf("nil expression")
325		}
326	
327		switch node.Kind {
328		case ast.NodeIntLit:
329			// Parse integer literal
330			var val int64
331			fmt.Sscanf(node.Value, "%d", &val)
332			return Operand{IsImm: true, ImmVal: val}, nil
333	
334		case ast.NodeIdent:
335			return Operand{Name: node.Value}, nil
336	
337		case ast.NodeBinaryExpr:
338			return g.genBinaryExpr(node)
339	
340		case ast.NodeCallExpr:
341			return g.genCallExpr(node)
342	
343		default:
344			return Operand{}, fmt.Errorf("unsupported expression kind: %d", node.Kind)
345		}
346	}
347	
348	// genBinaryExpr generates IR for a binary expression
349	func (g *Generator) genBinaryExpr(node *ast.Node) (Operand, error) {
350		if len(node.Children) < 2 {
351			return Operand{}, fmt.Errorf("binary expression requires 2 operands")
352		}
353	
354		left, err := g.genExpr(node.Children[0])
355		if err != nil {
356			return Operand{}, err
357		}
358	
359		right, err := g.genExpr(node.Children[1])
360		if err != nil {
361			return Operand{}, err
362		}
363	
364		result := g.newTemp()
365		op := g.opcodeFromOp(node.Value)
366	
367		g.emit(Instruction{
368			Op:   op,
369			Dest: result,
370			Src1: left,
371			Src2: right,
372		})
373	
374		return result, nil
375	}
376	
377	// genCallExpr generates IR for a function call
378	func (g *Generator) genCallExpr(node *ast.Node) (Operand, error) {
379		if len(node.Children) == 0 {
380			return Operand{}, fmt.Errorf("call expression requires function name")
381		}
382	
383		fnName := node.Children[0].Value
384	
385		// Emit parameters
386		for i := 1; i < len(node.Children); i++ {
387			argOp, err := g.genExpr(node.Children[i])
388			if err != nil {
389				return Operand{}, err
390			}
391			g.emit(Instruction{
392				Op:   OpParam,
393				Src1: argOp,
394			})
395		}
396	
397		// Emit call
398		result := g.newTemp()
399		g.emit(Instruction{
400			Op:   OpCall,
401			Dest: result,
402			Fn:   fnName,
403		})
404	
405		return result, nil
406	}
407	
408	// Helper functions
409	
410	func (g *Generator) newTemp() Operand {
411		temp := Operand{
412			IsTemp: true,
413			Name:   fmt.Sprintf("t%d", g.tempCount),
414		}
415		g.tempCount++
416		return temp
417	}
418	
419	func (g *Generator) newLabel(prefix string) string {
420		label := fmt.Sprintf("L_%s_%d", prefix, g.labelCount)
421		g.labelCount++
422		return label
423	}
424	
425	func (g *Generator) emit(instr Instruction) {
426		if g.currentFn != nil {
427			g.currentFn.Body = append(g.currentFn.Body, instr)
428		} else {
429			g.program.Main = append(g.program.Main, instr)
430		}
431	}
432	
433	func (g *Generator) opcodeFromOp(op string) Opcode {
434		switch op {
435		case "+":
436			return OpAdd
437		case "-":
438			return OpSub
439		case "*":
440			return OpMul
441		case "/":
442			return OpDiv
443		case "==":
444			return OpEq
445		case "!=":
446			return OpNe
447		case "<":
448			return OpLt
449		case ">":
450			return OpGt
451		case "<=":
452			return OpLe
453		case ">=":
454			return OpGe
455		default:
456			return OpNoop
457		}
458	}
